-- Sprint 1 (docs/improvements/HOME-HERO-PLAN.md §7, D-030, D-034): the home hero's cover images, as data.
-- Generated by scripts/build-hero-photos.mjs from two source files (not committed); the encoded images are
-- design/hero/hero-desktop.webp (landscape) and hero-mobile.webp (portrait). Each is added as the current photo
-- of its slot only if the slot is empty — the owner replaces either in Admin → Photos at any time (the old one
-- is kept, BR-1.17). The credit is the "home-hero" block's, shown on the image. The hero itself stays off until
-- the flag home.hero_v2 is switched on. Additive only.

INSERT INTO "ProfilePhoto" ("id", "purpose", "altText", "mimeType", "width", "height", "byteSize", "sha256", "fileData")
SELECT gen_random_uuid()::text, 'hero-desktop', 'A dark data-centre aisle lit by thin orange fibre-optic lines that run to a distant vanishing point', 'image/webp', 1536, 1024, 95052, 'a87d8c8446c2daa267d73f36aa6112f738d5488ce166c9ccf026374ab48e2ed6', decode('', 'base64')
WHERE NOT EXISTS (SELECT 1 FROM "ProfilePhoto" WHERE "purpose" = 'hero-desktop');

INSERT INTO "ProfilePhoto" ("id", "purpose", "altText", "mimeType", "width", "height", "byteSize", "sha256", "fileData")
SELECT gen_random_uuid()::text, 'hero-mobile', 'A dark data-centre aisle lit by thin orange fibre-optic lines that run to a distant vanishing point', 'image/webp', 1024, 1536, 72910, 'f7339608d2070e1c400da3318650f03415a473451c22faedb97d035f637c6d1b', decode('', 'base64')
WHERE NOT EXISTS (SELECT 1 FROM "ProfilePhoto" WHERE "purpose" = 'hero-mobile');

UPDATE "SiteContent"
SET "body" = "body" || jsonb_build_object('imageCredit', 'Image: AI-generated with ChatGPT')
WHERE "key" = 'home-hero' AND NOT ("body" ? 'imageCredit');
